import{_ as o,l as n,o as e,c as l,v as t,p as s,x as i,d,i as m,S as p}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"贝叶斯组合与参数不确定","description":"","frontmatter":{"title":"贝叶斯组合与参数不确定","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/bayesian-portfolio.md","filePath":"quant/bayesian-portfolio.md","lastUpdated":1789023840000}'),u={name:"quant/bayesian-portfolio.md"};function h(E,a,c,B,_,A){const r=n("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="贝叶斯组合与参数不确定" tabindex="-1">贝叶斯组合与参数不确定 <a class="header-anchor" href="#贝叶斯组合与参数不确定" aria-label="Permalink to &quot;贝叶斯组合与参数不确定&quot;">​</a></h1><div class="epigraph"><p>未知的 $\\mu$ 应积分掉，而不是用点估计塞进 Merton 公式；后验越散，有效风险厌恶越高，仓位越收缩。</p><footer>—— 对照 Jorion 对 Bayes–Stein 估计的组合应用；Black–Litterman 的均衡先验</footer></div><p><a href="/quant/garleanu-pedersen">上一课</a>在二次冲击下给出向平滑瞄准点的部分调整，瞄准点含未来信号预期，\\(\\Lambda\\) 必须来自执行模型。缺口是目标本身：GP 把 \\(\\pi^\\ast\\) 当已知再谈怎么交易，样本均值当 \\(\\mu\\) 会在历史运气最好的资产上杠杆。本课钉贝叶斯组合：对 \\(\\mu\\)（及 \\(\\Sigma\\)）求后验，决策最大化后验期望效用，权重向先验收缩。不重讲部分调整增益。主干装置见 <a href="/quant/black-litterman">Black–Litterman</a> 与 <a href="/quant/cov-shrinkage">收缩</a>；后课稳健优化默认已经分清后验平均与最坏情形。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>GP 的瞄准点把 \\(\\mu\\) 当已知；样本均值当 \\(\\mu\\)，Markowitz/Merton 会在历史运气最好的资产上杠杆。贝叶斯：给定先验与样本，对 \\(\\mu\\)（及 \\(\\Sigma\\)）求后验，决策是最大化后验期望效用，或等价地对后验预测分布做 Markowitz。结果通常是：权重向先验（常取均衡市值或 BL 均衡）收缩，有效 \\(\\gamma\\) 变大。问题是把「我们很不确定 \\(\\mu\\)」写成先验方差，而不是写成口头谨慎然后仍用点估计下单。</p><p>预测分布的方差 \\(=\\) 残差方差 \\(+\\) 参数不确定。短样本、高维时第二项主导，最优仓接近无风险或接近均衡，这是特征。</p><h3 id="与-bl-的分工" tabindex="-1">与 BL 的分工 <a class="header-anchor" href="#与-bl-的分工" aria-label="Permalink to &quot;与 BL 的分工&quot;">​</a></h3><p>BL 用均衡 \\(\\pi\\) 当先验均值，观点当似然。本课强调：即使没有观点，仅参数不确定也要求收缩。有观点时，观点的置信就是先验精度。不要既用 BL 又用另一套「再保守 50%」的随意分数，除非那 50% 来自后验计算。</p><p><span class="marginnote">对数效用对参数不确定特别脆：Kelly 课已说满 Kelly 在 \\(\\mu\\) 高估时破产风险升。贝叶斯 Kelly 自然分数化。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>先验：\\(\\mu\\) 向均衡或零超额（风险平价精神）；\\(\\Sigma\\) Inverse-Wishart 或因子。后验预测代入二次效用得 \\(\\pi\\)。高维用经验贝叶斯估计先验方差，避免拍 \\(\\tau\\)。对照：点估计 Markowitz vs 后验政策的样本外，对象是扣费 IR 与换手，不是样本内前沿。</p><p>动态：参数后验随数据更新，政策应慢，避免把噪声当新观点——与校准隔日罚同构。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>积分 \\(\\mu\\) 等于在效用里加一项对估计误差的厌恶。仓位下降、分散上升（不太敢集中押注历史赢家）。这与下一课稳健优化的最坏 \\(\\mu\\) 集合是两条路：贝叶斯对后验加权平均，稳健对集合取 min。前者需要先验，后者需要不确定集。</p>',14)),(e(),s(p,null,{default:i(()=>[m(r,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20Prior%5B%22%E5%85%88%E9%AA%8C%20%E5%9D%87%E8%A1%A1%E6%88%96%20BL%22%5D%20--%3E%20Post%5B%22%E5%90%8E%E9%AA%8C%E9%A2%84%E6%B5%8B%E5%88%86%E5%B8%83%22%5D%0A%20%20Data%5B%22%E6%A0%B7%E6%9C%AC%22%5D%20--%3E%20Post%0A%20%20Post%20--%3E%20Pi%5B%22%E6%9C%9F%E6%9C%9B%E6%95%88%E7%94%A8%E6%9C%80%E4%BC%98%E4%BB%93%20%E8%87%AA%E5%8A%A8%E6%94%B6%E7%BC%A9%22%5D%0A%20%20Point%5B%22%E7%82%B9%E4%BC%B0%E8%AE%A1%20%CE%BC%22%5D%20--%3E%20Expl%5B%22%E6%9D%83%E9%87%8D%E7%88%86%E7%82%B8%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>先验错了（均衡本身是错的模型）会把所有人拉向错误基准。稳健课处理先验也不信的情况。计算：全贝叶斯 MCMC 对日频再平衡太重，实务用共轭或 BL 闭式。不要把贝叶斯当成「可以用更短窗口」的许可证——短窗口让后验更散，仓位应更小。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>对参数积分后，仓位收缩、有效风险厌恶上升；这是政策，不只是估计技巧。</li><li>BL 是带均衡先验的实现；不要叠加无来源的再打折。</li><li>与稳健优化不同：平均后验 vs 最坏集合。</li><li>出处：Jorion, <em>Journal of Financial and Quantitative Analysis</em>, 1986（Bayes–Stein）；Black and Litterman, 1992。</li></ul>',4))])}const P=o(u,[["render",h]]);export{b as __pageData,P as default};
